window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b6bf136cfc7d6080"]={"versions": [{"id": "FIG-b6bf136cfc7d6080", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsdiagramm (UML State Machine) zur Logik des UDS-/AUTOSAR-DTC-Statusbits 1 (<code>TestFailedThisOperationCycle</code>) innerhalb des AUTOSAR Diagnostic Event Managers (Dem) der Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände:</strong></li>\n<li>Pseudo-Startzustand: <code>Initial state</code></li>\n<li>Operative Zustände: <code>TestFailedThisOperationCycle = FALSE</code> und <code>TestFailedThisOperationCycle = TRUE</code></li>\n<li><strong>Schnittstellen & API-Aufrufe:</strong></li>\n<li><code>Dem_SetEventStatus(EventId, EventStatus)</code> / <code>Dem_ReportErrorStatus(EventId, EventStatus)</code></li>\n<li><code>Dem_SetOperationCycleState(OperationCycleId, CycleState)</code></li>\n<li><code>Dem_&lt;...&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code> (referenziert über Anforderung <code>[SWS_Dem_00385]</code>)</li>\n<li><strong>Statuswerte & Enumeratoren:</strong></li>\n<li><code>DEM_EVENT_STATUS_PASSED</code></li>\n<li><code>DEM_EVENT_STATUS_FAILED</code></li>\n<li><code>DEM_CYCLE_STATE_START</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialisierung:</strong></li>\n<li>Übergang aus dem <code>Initial state</code> setzt Bit 1 (<code>TestFailedThisOperationCycle</code>) initial auf <code>FALSE</code>.</li>\n<li><strong>Zustandsübergänge:</strong></li>\n<li><code>FALSE -&gt; TRUE</code>: Ausgelöst durch <code>Dem_SetEventStatus</code> oder <code>Dem_ReportErrorStatus</code> mit <code>EventStatus = DEM_EVENT_STATUS_FAILED</code> (Bedingung <code>[B]</code>).</li>\n<li><code>TRUE -&gt; FALSE</code>: Ausgelöst durch Start eines Betriebszyklus mittels <code>Dem_SetOperationCycleState(OperationCycleId, CycleState = DEM_CYCLE_STATE_START)</code> (Bedingung <code>[A]</code>) ODER durch das Löschen von DTCs via <code>Dem_&lt;...&gt;ClearDTC(...)</code> gemäß <code>[SWS_Dem_00385]</code>.</li>\n<li><strong>Selbsttransitionen:</strong></li>\n<li>Im Zustand <code>FALSE</code>: Aufruf von <code>Dem_[SetEvent|ReportError]Status</code> mit <code>EventStatus = DEM_EVENT_STATUS_PASSED</code> belässt das Bit auf <code>FALSE</code>.</li>\n<li>Im Zustand <code>TRUE</code>: Aufruf von <code>Dem_[SetEvent|ReportError]Status</code> mit <code>EventStatus = DEM_EVENT_STATUS_FAILED</code> oder <code>DEM_EVENT_STATUS_PASSED</code> belässt das Bit auf <code>TRUE</code> (einmal gesetzter Fehler bleibt über den aktuellen Betriebszyklus hinweg erhalten).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Bit 1 speichert gemäß ISO 14229-1 (UDS) und AUTOSAR-Dem-Spezifikation, ob während des laufenden Betriebszyklus mindestens einmal ein Fehler (<code>DEM_EVENT_STATUS_FAILED</code>) aufgetreten ist.</li>\n<li>Ein nachfolgendes Testergebnis <code>DEM_EVENT_STATUS_PASSED</code> setzt Bit 1 nicht zurück, solange der Betriebszyklus aktiv ist.</li>\n<li>Ein Reset auf <code>FALSE</code> erfolgt ausschließlich bei einem Neustart des zugeordneten Operationszyklus (<code>DEM_CYCLE_STATE_START</code>) oder durch eine explizite Clear-DTC-Anforderung.</li>\n</ul>"}, {"id": "FIG-89d6cf02bbcd1b22", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsdiagramm (UML State Machine) zur Logik des UDS-/AUTOSAR-DTC-Statusbits 1 (<code>TestFailedThisOperationCycle</code>) innerhalb des AUTOSAR Diagnostic Event Managers (Dem) der Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände:</strong></li>\n<li>Pseudo-Startzustand: <code>Initial state</code></li>\n<li>Operative Zustände: <code>TestFailedThisOperationCycle = FALSE</code> und <code>TestFailedThisOperationCycle = TRUE</code></li>\n<li><strong>Schnittstellen & API-Aufrufe:</strong></li>\n<li><code>Dem_SetEventStatus(EventId, EventStatus)</code> / <code>Dem_ReportErrorStatus(EventId, EventStatus)</code></li>\n<li><code>Dem_SetOperationCycleState(OperationCycleId, CycleState)</code></li>\n<li><code>Dem_&lt;...&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code> (referenziert über Anforderung <code>[SWS_Dem_00385]</code>)</li>\n<li><strong>Statuswerte & Enumeratoren:</strong></li>\n<li><code>DEM_EVENT_STATUS_PASSED</code></li>\n<li><code>DEM_EVENT_STATUS_FAILED</code></li>\n<li><code>DEM_CYCLE_STATE_START</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialisierung:</strong></li>\n<li>Übergang aus dem <code>Initial state</code> setzt Bit 1 (<code>TestFailedThisOperationCycle</code>) initial auf <code>FALSE</code>.</li>\n<li><strong>Zustandsübergänge:</strong></li>\n<li><code>FALSE -&gt; TRUE</code>: Ausgelöst durch <code>Dem_SetEventStatus</code> oder <code>Dem_ReportErrorStatus</code> mit <code>EventStatus = DEM_EVENT_STATUS_FAILED</code> (Bedingung <code>[B]</code>).</li>\n<li><code>TRUE -&gt; FALSE</code>: Ausgelöst durch Start eines Betriebszyklus mittels <code>Dem_SetOperationCycleState(OperationCycleId, CycleState = DEM_CYCLE_STATE_START)</code> (Bedingung <code>[A]</code>) ODER durch das Löschen von DTCs via <code>Dem_&lt;...&gt;ClearDTC(...)</code> gemäß <code>[SWS_Dem_00385]</code>.</li>\n<li><strong>Selbsttransitionen:</strong></li>\n<li>Im Zustand <code>FALSE</code>: Aufruf von <code>Dem_[SetEvent|ReportError]Status</code> mit <code>EventStatus = DEM_EVENT_STATUS_PASSED</code> belässt das Bit auf <code>FALSE</code>.</li>\n<li>Im Zustand <code>TRUE</code>: Aufruf von <code>Dem_[SetEvent|ReportError]Status</code> mit <code>EventStatus = DEM_EVENT_STATUS_FAILED</code> oder <code>DEM_EVENT_STATUS_PASSED</code> belässt das Bit auf <code>TRUE</code> (einmal gesetzter Fehler bleibt über den aktuellen Betriebszyklus hinweg erhalten).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Bit 1 speichert gemäß ISO 14229-1 (UDS) und AUTOSAR-Dem-Spezifikation, ob während des laufenden Betriebszyklus mindestens einmal ein Fehler (<code>DEM_EVENT_STATUS_FAILED</code>) aufgetreten ist.</li>\n<li>Ein nachfolgendes Testergebnis <code>DEM_EVENT_STATUS_PASSED</code> setzt Bit 1 nicht zurück, solange der Betriebszyklus aktiv ist.</li>\n<li>Ein Reset auf <code>FALSE</code> erfolgt ausschließlich bei einem Neustart des zugeordneten Operationszyklus (<code>DEM_CYCLE_STATE_START</code>) oder durch eine explizite Clear-DTC-Anforderung.</li>\n</ul>"}], "trans": [{"from": "FIG-b6bf136cfc7d6080", "to": "FIG-89d6cf02bbcd1b22", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
